function renderSpreadsheetRecord(id) {
  const record = spreadsheetArchive[id];
  if (!record) return "";
  // Mostrar apenas dados concretos do levantamento, sem transformar lacunas em listas de "não indicado".
  const fields = [];
  if (record.location) fields.push(`Local registado no levantamento: ${record.location}`);
  if (record.date) fields.push(`Data registada no levantamento: ${record.date}`);
  if (record.themes && !/não indicado|não indicada/i.test(record.themes)) fields.push(`Temas e trabalhos registados: ${record.themes}`);
  if (record.observations && !/não indicado|não indicada/i.test(record.observations)) fields.push(`Participação: ${record.observations}`);
  if (record.additional && !/não indicado|não indicada/i.test(record.additional)) fields.push(`Nota complementar: ${record.additional}`);
  if (!fields.length) return "";
  return renderDetailSection("Dados do levantamento", fields);
}

