// Cada ENJE possui a sua própria imagem.
// Para trocar a fotografia, substitua o ficheiro correspondente em /images/
// sem precisar alterar o restante do JavaScript.
const IMAGE_BASE = "images/";

const grid = document.getElementById("encounterGrid");
const emptyState = document.getElementById("emptyState");
const searchInput = document.getElementById("searchInput");
const yearFilter = document.getElementById("yearFilter");

function renderTimeline() {
  const timeline = document.getElementById("timelineList");
  if (!timeline) return;

  timeline.innerHTML = encounters.map(item => `
    <article class="timeline-item">
      <span class="timeline-year">${item.year}</span>
      <div class="timeline-line"></div>
      <div class="timeline-card ${item.id === 6 || item.id === 38 ? "featured" : ""}">
        <span class="card-number">${item.number}</span>
        <h3>${item.title}</h3>
        <p class="location">${item.location}</p>
        <p>${item.dates}</p>
        <button class="details-btn" data-enje="${item.id}">Ver memória do encontro →</button>
      </div>
    </article>
  `).join("");

  timeline.querySelectorAll("[data-enje]").forEach(button => {
    button.addEventListener("click", () => openModal(Number(button.dataset.enje)));
  });
}

function setupHorizontalTimeline() {
  const viewport = document.getElementById("timelineViewport");
  if (!viewport || viewport.dataset.ready === "true") return;
  viewport.dataset.ready = "true";

  document.querySelectorAll("[data-timeline-scroll]").forEach(button => {
    button.addEventListener("click", () => {
      const direction = Number(button.dataset.timelineScroll) || 1;
      viewport.scrollBy({ left: direction * Math.max(280, viewport.clientWidth * 0.78), behavior: "smooth" });
    });
  });

  // Permite arrastar a linha do tempo com o rato; o toque continua nativo no telemóvel.
  let dragging = false, startX = 0, startScroll = 0;
  viewport.addEventListener("pointerdown", event => {
    if (event.pointerType !== "mouse" || event.button !== 0) return;
    if (event.target.closest("button, a, input, select, textarea")) return;
    dragging = true;
    startX = event.clientX;
    startScroll = viewport.scrollLeft;
    viewport.classList.add("is-dragging");
  });
  window.addEventListener("pointermove", event => {
    if (!dragging) return;
    viewport.scrollLeft = startScroll - (event.clientX - startX);
  });
  window.addEventListener("pointerup", () => {
    dragging = false;
    viewport.classList.remove("is-dragging");
  });
  viewport.addEventListener("keydown", event => {
    if (event.key === "ArrowRight") { event.preventDefault(); viewport.scrollBy({left: 280, behavior: "smooth"}); }
    if (event.key === "ArrowLeft") { event.preventDefault(); viewport.scrollBy({left: -280, behavior: "smooth"}); }
  });
  viewport.tabIndex = 0;
}

function renderCards() {
  const query = searchInput.value.toLowerCase().trim();
  const year = yearFilter.value;

  const filtered = encounters.filter(item => {
    const searchable = [
      item.number, item.year, item.title, item.location, item.dates,
      item.theme, item.organization, item.notes,
      ...(pressArchive[item.id]?.headlines || []),
      pressArchive[item.id]?.type,
      ...(pressArchive[item.id]?.details || []),
      pressArchive[item.id]?.note
    ].join(" ").toLowerCase();

    return searchable.includes(query) &&
      (year === "all" || String(item.year) === year);
  });

  grid.innerHTML = filtered.map(item => `
    <article class="encounter-card">
      <div class="encounter-photo-wrap">
        <img src="${IMAGE_BASE + item.image.replace("images/", "")}"
             alt="Fotografia do ${item.number}"
             class="encounter-photo"
             onerror="this.src='images/placeholder.jpg'">
      </div>
      <div class="encounter-info">
        <span class="year">${item.year}</span>
        <h3>${item.number}</h3>
        <p><strong>${item.title}</strong></p>
        <p>${item.location}</p>
        <p>${item.dates}</p>
      </div>
      <button class="details-btn" data-enje="${item.id}">Abrir memória →</button>
    </article>
  `).join("");

  emptyState.style.display = filtered.length ? "none" : "block";

  document.querySelectorAll("[data-enje]").forEach(button => {
    button.addEventListener("click", () => openModal(Number(button.dataset.enje)));
  });
}

function escapeHTML(value) {
  return String(value ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#039;");
}

function renderDetailSection(title, content) {
  if (!content || (Array.isArray(content) && content.length === 0)) return "";
  return `
    <section class="modal-section">
      <h3>${escapeHTML(title)}</h3>
      ${Array.isArray(content)
        ? `<ul>${content.map(item => `<li>${escapeHTML(item)}</li>`).join("")}</ul>`
        : `<p>${escapeHTML(content)}</p>`}
    </section>
  `;
}


let activeGalleryImages = [];
let activeGalleryIndex = 0;
let activeGalleryEncounter = null;

function setGalleryImages(images, item) {
  activeGalleryImages = images;
  activeGalleryIndex = 0;
  activeGalleryEncounter = item;
  const gallery = document.getElementById("modalGallery");
  gallery.classList.toggle("single-photo", images.length <= 1);
  document.getElementById("galleryPrev").disabled = images.length <= 1;
  document.getElementById("galleryNext").disabled = images.length <= 1;
  showGalleryImage();
}

function showGalleryImage() {
  if (!activeGalleryImages.length || !activeGalleryEncounter) return;
  const image = document.getElementById("modalImage");
  const path = activeGalleryImages[activeGalleryIndex];
  image.src = path.startsWith("http") ? path : path;
  image.alt = `Fotografia ${activeGalleryIndex + 1} de ${activeGalleryImages.length} — ${activeGalleryEncounter.number}`;
  image.onerror = () => {
    image.onerror = null;
    image.src = activeGalleryEncounter.image;
  };
  document.getElementById("galleryCounter").textContent =
    `${activeGalleryIndex + 1} / ${activeGalleryImages.length}`;
}

document.getElementById("galleryPrev").addEventListener("click", () => {
  if (activeGalleryImages.length <= 1) return;
  activeGalleryIndex = (activeGalleryIndex - 1 + activeGalleryImages.length) % activeGalleryImages.length;
  showGalleryImage();
});
document.getElementById("galleryNext").addEventListener("click", () => {
  if (activeGalleryImages.length <= 1) return;
  activeGalleryIndex = (activeGalleryIndex + 1) % activeGalleryImages.length;
  showGalleryImage();
});

