async function loadEncounterGallery(item) {
  const folder = `enje-${item.year}-${String(item.id).padStart(2, "0")}`;

  // 1) Método preferencial: PHP lista em tempo real os ficheiros da pasta.
  try {
    const response = await fetch(`gallery.php?folder=${encodeURIComponent(folder)}&v=${Date.now()}`, { cache: "no-store" });
    if (response.ok) {
      const result = await response.json();
      if (Array.isArray(result.images) && result.images.length) return result.images;
    }
  } catch (_) {
    // file:// e alojamentos sem PHP não conseguem usar este endpoint.
  }

  // 2) Tenta o manifesto externo em servidores HTTP.
  try {
    const response = await fetch(`gallery-manifest.json?v=${Date.now()}`, { cache: "no-store" });
    if (response.ok) {
      const manifest = await response.json();
      const images = manifest[folder];
      if (Array.isArray(images) && images.length) return images;
    }
  } catch (_) {
    // fetch() de ficheiros locais costuma ser bloqueado pelos navegadores.
  }

  // 3) Fallback incorporado: permite testar o ZIP abrindo index.html diretamente.
  const localImages = EMBEDDED_GALLERY_MANIFEST[folder];
  if (Array.isArray(localImages) && localImages.length) return localImages;

  return [item.image];
}

function openModal(id) {
  const item = encounters.find(encounter => encounter.id === id);
  if (!item) return;

  document.getElementById("modalNumber").textContent = item.number;
  document.getElementById("modalTitle").textContent = item.title;
  document.getElementById("modalLocation").textContent =
    `${item.location} · ${item.dates}`;

  document.getElementById("modalDescription").textContent = item.description;

  document.getElementById("modalMeta").innerHTML = `
    <span>${escapeHTML(item.year)}</span>
    <span>${escapeHTML(item.location)}</span>
    ${item.theme ? `<span>Tema: ${escapeHTML(item.theme)}</span>` : ""}
    ${item.organization ? `<span>Organização: ${escapeHTML(item.organization)}</span>` : ""}
  `;

  const details = document.getElementById("modalDetails");
  const press = pressArchive[item.id];
  // Exibir a ficha sempre que o próprio encontro tiver informação documental.
  // Antes, apenas o I ENJE era avaliado pelos seus campos; por isso, o XXXVIII ENJE
  // tinha programa e oficinas no objeto, mas a janela não mostrava as secções.
  const hasItemDetails = [
    item.venue, item.origin, item.objectives, item.program, item.workshops,
    item.participants, item.observers, item.presentations, item.plannedProgram,
    item.regions, item.coordination, item.culturalRecord, item.photographer,
    item.documents, item.archivalMaterial, item.conclusions,
    item.historicalImportance, item.nameTransition, item.legacy, item.notes, item.sources
  ].some(value => Array.isArray(value) ? value.length > 0 : Boolean(value));
  const hasDetailedData = hasItemDetails || Boolean(press) || Boolean(spreadsheetArchive[item.id]);

  if (hasDetailedData) {
    details.innerHTML = [
      renderDetailSection("Local", item.venue),
      renderDetailSection("Como nasceu a ideia", item.origin),
      renderDetailSection("Objetivos", item.objectives),
      renderDetailSection("Programa do encontro", item.program),
      renderDetailSection("Oficinas e apresentações", item.workshops),
      renderDetailSection("Participantes", item.participants),
      renderDetailSection("Observadores identificados", item.observers),
      renderDetailSection("Temas e apresentações", item.presentations),
      renderDetailSection("Programa previsto", item.plannedProgram),
      renderDetailSection("Regiões identificadas", item.regions),
      renderDetailSection("Coordenação", item.coordination),
      renderDetailSection("Registo cultural", item.culturalRecord),
      renderDetailSection("Fotografia", item.photographer),
      renderDetailSection("Documentação preservada", item.documents || "Em fase de levantamento."),
      renderDetailSection("Arquivo fotográfico e documental", item.archivalMaterial || "Em fase de levantamento."),
      renderDetailSection("Conclusões", item.conclusions),
      renderDetailSection("Importância histórica", item.historicalImportance),
      renderDetailSection("Transição para a designação ENJE", item.nameTransition),
      renderDetailSection("Legado", item.legacy),
      renderDetailSection("Notas", item.notes || "Em fase de levantamento."),
      renderDetailSection("Fontes", item.sources),
      renderSpreadsheetRecord(item.id),
      renderDetailSection("Manchetes e documentos", press?.headlines?.length ? press.headlines : "Em fase de levantamento."),
      renderDetailSection("Informações acrescentadas a partir dos recortes", press?.details),
      renderDetailSection("Notas de verificação documental", press?.note)
    ].join("");
  } else {
    details.innerHTML = "";
  }

  const modal = document.getElementById("enjeModal");
  loadEncounterGallery(item).then(images => {
    setGalleryImages(images.length ? images : [item.image], item);
  });

  modal.classList.add("open");
  modal.setAttribute("aria-hidden", "false");
  document.body.style.overflow = "hidden";
}
function closeModal() {
  const modal = document.getElementById("enjeModal");
  modal.classList.remove("open");
  modal.setAttribute("aria-hidden", "true");
  document.body.style.overflow = "";
}

searchInput.addEventListener("input", renderCards);
yearFilter.addEventListener("change", renderCards);

document.querySelectorAll("[data-close-modal]").forEach(el => {
  el.addEventListener("click", closeModal);
});

document.addEventListener("keydown", event => {
  if (event.key === "Escape") closeModal();
});

const menuToggle = document.querySelector(".menu-toggle");
const navLinks = document.querySelector(".nav-links");

menuToggle.addEventListener("click", () => {
  const active = navLinks.classList.toggle("active");
  menuToggle.setAttribute("aria-expanded", String(active));
});

document.querySelectorAll(".nav-links a").forEach(link => {
  link.addEventListener("click", () => {
    navLinks.classList.remove("active");
    menuToggle.setAttribute("aria-expanded", "false");
  });
});

// Filtros de anos gerados automaticamente a partir do arquivo.
const years = [...new Set(encounters.map(item => item.year))].sort((a, b) => a - b);
years.forEach(year => {
  const option = document.createElement("option");
  option.value = year;
  option.textContent = year;
  yearFilter.appendChild(option);
});

renderTimeline();
setupHorizontalTimeline();
renderCards();

// Garante que o link do rodapé leva ao início da página em todos os navegadores.
const backToTop = document.getElementById("backToTop");
if (backToTop) {
  backToTop.addEventListener("click", event => {
    event.preventDefault();
    window.scrollTo({ top: 0, behavior: "smooth" });
    history.replaceState(null, "", window.location.pathname + window.location.search);
  });
}
